using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using Microsoft.UI.Xaml.Media.Imaging;
using Microsoft.UI.Windowing;
using System.Diagnostics;
using System.IO.Pipes;
using System.Text;
using System.Text.Json.Nodes;
namespace WirePulse.WindowsSettings;
sealed class ExperienceWindow:Window {
 readonly string pipe;readonly Canvas canvas=new();readonly Image logo=new(){Width=112,Height=112};readonly TextBlock brand=new(){Text="WirePulse",FontSize=30,FontWeight=Microsoft.UI.Text.FontWeights.Bold};readonly StackPanel body=new(){Width=548,Spacing=14};readonly DispatcherTimer animation=new(){Interval=TimeSpan.FromMilliseconds(16)},poll=new(){Interval=TimeSpan.FromMilliseconds(350)};readonly Stopwatch time=new();JsonObject state=new();bool expanded,loading=true;double transition=-1,scale=1;string page="intro";Windows.Graphics.PointInt32 center;
 public ExperienceWindow(string[] args){pipe=args[Array.IndexOf(args,"--pipe")+1];Title="WirePulse";SystemBackdrop=new DesktopAcrylicBackdrop();ExtendsContentIntoTitleBar=true;if(AppWindow.Presenter is OverlappedPresenter presenter){presenter.SetBorderAndTitleBar(false,false);presenter.IsResizable=false;presenter.IsMaximizable=false;}
  AppWindow.Resize(new(320,280));var area=DisplayArea.GetFromWindowId(AppWindow.Id,DisplayAreaFallback.Primary).WorkArea;center=new(area.X+area.Width/2,area.Y+area.Height/2);AppWindow.Move(new(center.X-160,center.Y-140));
  var root=new Border{CornerRadius=new CornerRadius(28),BorderThickness=new Thickness(1),BorderBrush=new SolidColorBrush(Windows.UI.Color.FromArgb(70,255,255,255)),Background=new SolidColorBrush(Windows.UI.Color.FromArgb(75,24,28,38)),Child=canvas};root.RequestedTheme=ElementTheme.Dark;Content=root;
  logo.Source=new BitmapImage(new Uri(System.IO.Path.Combine(AppContext.BaseDirectory,"..","Assets","WirePulse.png")));canvas.Children.Add(logo);canvas.Children.Add(brand);canvas.Children.Add(body);Canvas.SetLeft(body,36);Canvas.SetTop(body,106);body.Visibility=Visibility.Collapsed;Layout(0);
  animation.Tick+=(_,_)=>{if(loading)return;double t=time.Elapsed.TotalSeconds;if(page=="intro"){double reveal=Math.Clamp(t/(state["duration"]?.GetValue<double>()??6.136),0,1);brand.Opacity=Math.Min(1,reveal*2);brand.Clip=new RectangleGeometry{Rect=new Windows.Foundation.Rect(0,0,Math.Max(1,brand.ActualWidth)*reveal,60)};if(t>=(state["duration"]?.GetValue<double>()??6.136)+.2){if(state["setup"]?.GetValue<bool>()==true)Setup();else if(state["news"]?.GetValue<bool>()==true)News();else Close();}}else if(transition>=0){double p=Math.Clamp((t-transition)/.8,0,1),e=1-Math.Pow(1-p,3);Layout(e);body.Opacity=e;if(p>=1){transition=-1;animation.Stop();}}};
  poll.Tick+=async(_,_)=>{if(page!="update")return;try{state=await Request("get");status.Text=state["status"]?.GetValue<string>()??"";progress.Value=(state["progress"]?.GetValue<double>()??0)*100;actions.IsEnabled=state["installing"]?.GetValue<bool>()!=true;}catch{state["installing"]=false;Close();}};
  root.Loaded+=async(_,_)=>{try{state=await Request("get");scale=root.XamlRoot.RasterizationScale;Layout(0);loading=false;if(state["direct"]?.GetValue<bool>()!=true&&state["update"]==null)await Request("start");time.Start();if(args.Contains("--experience-test")){Setup();Layout(1);if(body.Children.OfType<CheckBox>().Count()!=4)throw new Exception("Missing native setup choices");News();Layout(1);Update();Layout(1);if(actions.Children.Count!=3)throw new Exception("Missing update actions");await Request("tested");Close();return;}if(state["update"]!=null)Update();else if(state["direct"]?.GetValue<bool>()==true)News();else animation.Start();}catch(Exception e){body.Visibility=Visibility.Visible;body.Children.Add(Text(e.Message));}};
  Closed+=(_,_)=>{animation.Stop();poll.Stop();};AppWindow.Closing+=(_,e)=>{if(state["installing"]?.GetValue<bool>()==true)e.Cancel=true;};
 }
 async Task<JsonObject> Request(string op,JsonObject? data=null){data??=new();data["op"]=op;using var socket=new NamedPipeClientStream(".",pipe,PipeDirection.InOut,PipeOptions.Asynchronous);using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(10));await socket.ConnectAsync(timeout.Token);using var reader=new StreamReader(socket,Encoding.UTF8,leaveOpen:true);using var writer=new StreamWriter(socket,new UTF8Encoding(false),leaveOpen:true){AutoFlush=true};await writer.WriteLineAsync(data.ToJsonString());var reply=JsonNode.Parse(await reader.ReadLineAsync(timeout.Token)??"{}")!.AsObject();if(reply["error"]!=null)throw new Exception(reply["error"]!.GetValue<string>());return reply;}
 static TextBlock Text(string value,double size=15)=>new(){Text=L10n.Text(value),FontSize=size,TextWrapping=TextWrapping.Wrap,Foreground=new SolidColorBrush(Windows.UI.Color.FromArgb(255,240,242,248))};
 Button Button(string title,Func<Task> action){var b=new Button{Content=L10n.Text(title)};b.Click+=async(_,_)=>{b.IsEnabled=false;try{await action();}catch(Exception e){body.Children.Add(Text(e.Message));}finally{b.IsEnabled=true;}};return b;}
 CheckBox Check(string title,bool value){var c=new CheckBox{Content=L10n.Text(title),IsChecked=value};body.Children.Add(c);return c;}
 void Expand(){brand.Clip=null;brand.Opacity=1;body.Visibility=Visibility.Visible;if(!expanded){expanded=true;transition=time.Elapsed.TotalSeconds;animation.Start();}else{Layout(1);body.Opacity=1;}if(page!="update")_=Request("expanded");}
 void Layout(double p){int w=(int)(320+300*p),h=(int)(280+360*p);AppWindow.MoveAndResize(new(center.X-(int)(w*scale)/2,center.Y-(int)(h*scale)/2,(int)(w*scale),(int)(h*scale)));logo.Width=logo.Height=112-70*p;Canvas.SetLeft(logo,104-76*p);Canvas.SetTop(logo,42-18*p);brand.FontSize=30-8*p;Canvas.SetLeft(brand,86-2*p);Canvas.SetTop(brand,174-143*p);}
 async Task Finish(){body.IsHitTestVisible=false;await Request("finish");for(int i=0;i<30;i++){await Task.Delay(100);var result=await Request("get");if(result["finished"]?.GetValue<bool>()==true)break;}Close();}
 void Setup(){page="setup";body.Children.Clear();body.Children.Add(Text("Vamos a preparar tu escritorio",24));var startup=Check("Abrir WirePulse al iniciar sesión",state["startup"]?.GetValue<bool>()==true);var priority=Check("Inicio prioritario (Windows)",state["priority"]?.GetValue<bool>()==true);var automatic=Check("Comprobar actualizaciones automáticamente",state["automatic"]?.GetValue<bool>()==true);var splash=Check("Mostrar la splash en cada inicio",state["splash"]?.GetValue<bool>()==true);var channel=new ComboBox{ItemsSource=new[]{L10n.Text("Estable"),L10n.Text("Beta (prereleases)")},SelectedIndex=state["channel"]?.GetValue<string>()=="beta"?1:0};body.Children.Add(channel);body.Children.Add(Button("Continuar",async()=>{state=await Request("save",new(){["startup"]=startup.IsChecked==true,["priority"]=priority.IsChecked==true,["automatic"]=automatic.IsChecked==true,["splash"]=splash.IsChecked==true,["channel"]=channel.SelectedIndex==1?"beta":"stable"});if(state["news"]?.GetValue<bool>()==true)News();else{await Finish();}}));Expand();}
 void News(){page="news";body.Children.Clear();var title=Text("Novedades de\nWirePulse",32);title.FontWeight=Microsoft.UI.Text.FontWeights.Bold;title.TextAlignment=TextAlignment.Center;body.Children.Add(title);body.Children.Add(Text(state["version"]?.GetValue<string>()??"",13));var rows=new StackPanel{Spacing=20};foreach(var note in state["notes"]?.AsArray()??[]){var heading=Text(note?["title"]?.GetValue<string>()??"",19);heading.FontWeight=Microsoft.UI.Text.FontWeights.SemiBold;rows.Children.Add(heading);rows.Children.Add(Text(note?["description"]?.GetValue<string>()??""));}body.Children.Add(new ScrollViewer{Content=rows,MaxHeight=320});var mute=Button("Silenciar música",async()=>{state=await Request("mute");});var finish=Button("Continuar",async()=>{await Request("ack");await Finish();});body.Children.Add(new StackPanel{Orientation=Orientation.Horizontal,Spacing=12,Children={mute,finish}});Expand();}
 readonly TextBlock status=Text("Se descargará desde GitHub y se verificará antes de instalar.");readonly ProgressBar progress=new(){Minimum=0,Maximum=100};readonly StackPanel actions=new(){Spacing=12};
 void Update(){page="update";body.Children.Clear();body.Children.Add(Text("Hay una nueva versión de WirePulse.",24));body.Children.Add(Text((state["version"]?.GetValue<string>()??"")+" → "+(state["update"]?.GetValue<string>()??"")));body.Children.Add(status);body.Children.Add(progress);actions.Children.Add(Button("Actualizar",async()=>{state=await Request("install");}));actions.Children.Add(Button("Omitir esta versión",async()=>{await Request("skip");Close();}));actions.Children.Add(Button("No me vuelvas a preguntar",async()=>{await Request("never");Close();}));body.Children.Add(actions);Expand();poll.Start();}
}
